# Mine floor layout A (floors 3, 6, 9, ...): one big cavern around a rock island and a pool.
# '.' and ',' are open ground where areas.c scatters rocks and ore each visit; '_' stays clear.
# U is the ladder back up (arrive below it), the lift stands in the north wall (stops every 5th floor).
map MINE_A set=MINE w=16 h=16 music=MINE
key c MINE_CEIL block
key # MINE_WALL block
key t MINE_WALL_TORCH block
key . MINE_FLOOR walk
key , MINE_FLOOR2 walk
key _ MINE_FLOOR3 walk
key U MINE_LADDER_UP block
key ~ MINE_PUDDLE water
key p MINE_PILLAR block
grid
cccccccccccccccc
c#tU###t####_#tc
c._____.,..____c
c..___..,..._..c
c.,......,.....c
c....cccc...,..c
c..,.####....~~c
c,.........,.~~c
c....p.........c
c..,......ccc..c
c.........###.,c
c.,..cc........c
c....##...,..p.c
c..,.....,.....c
c.......,...,..c
cccccccccccccccc
place MINE_LIFT 12 1 act=LIFT
act 3 1 LADDERUP
